sys_security_acl.script:
/* global sn_hr_core */
var lcns = new sn_hr_core.hr_license();
var hasAccess = lcns.hasHrAccess(current.getTableName());
var impersonateCheck = new sn_hr_core.hr_CoreUtils().impersonateCheck();
var isInteractive = gs.getSession().isInteractive();

if ((isInteractive && impersonateCheck) || !hasAccess) {
    answer = false;
} else if (new sn_hr_core.hr_Case(current, gs).canReadCase()) {
    answer = true;
} else {
    answer = false;
}

//BUG#205236 - Employees should not see their own case record for all OHS and LR cases
